INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (9,9,'["Quels logiciels de dessin technique maîtrisez-vous (AutoCAD, Revit, SketchUp…) et à quel niveau d''utilisation vous situez-vous concrètement ?", "Comment procédez-vous pour réaliser un plan d''exécution à partir d''un avant-projet sommaire fourni par un architecte ?", "Citez les principales normes de construction applicables au Maroc que vous avez été amené à consulter ou à appliquer dans votre travail.", "Décrivez une mission concrète que vous avez réalisée durant votre année d''expérience et quel a été votre rôle exact dans cette mission.", "Avez-vous déjà travaillé sur un projet de bâtiment public ou d''infrastructure territoriale ? Si oui, quelles en étaient les particularités par rapport au secteur privé ?", "Quelles difficultés techniques avez-vous rencontrées dans votre parcours et comment les avez-vous surmontées ?", "Pourquoi souhaitez-vous rejoindre une agence publique plutôt que de continuer dans le secteur privé ou libéral ?", "Où vous voyez-vous professionnellement dans 3 à 5 ans, et en quoi ce poste s''inscrit-il dans cette trajectoire ?", "Que savez-vous du rôle et des missions de l''ADER Fès-Meknès, et quels projets de développement territorial de la région connaissez-vous ?", "Selon vous, quelles sont les contraintes spécifiques d''un projet architectural mené dans le cadre d''un marché public au Maroc ?"]','[]','{}','2026-08-27 13:27:12.425201') ON CONFLICT (id) DO NOTHING;